package com.gt7.bridge.mobile;

import android.app.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import android.graphics.*;
import android.content.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.text.*;
import java.util.*;

public class MainActivity extends Activity{
 static final String VERSION="v1.4";
 static final String PREF="gt7_v14_sessions";
 static final String URL_KEY="bridge_url", TRACK_KEY="track_name", CAR_KEY="car_name", LAPS_KEY="laps_db";
 static final String DEFAULT_URL="http://192.168.1.70:8787";
 Handler handler=new Handler(Looper.getMainLooper());
 MainView view; JSONObject flat=new JSONObject(); String bridgeUrl,trackName,carName,lastSavedLap=""; boolean running=false;
 Runnable loop=new Runnable(){public void run(){loadTelemetry();handler.postDelayed(this,500);}};

 public void onCreate(Bundle b){super.onCreate(b);requestWindowFeature(Window.FEATURE_NO_TITLE);getWindow().setFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN,WindowManager.LayoutParams.FLAG_FULLSCREEN);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);SharedPreferences sp=getSharedPreferences(PREF,0);bridgeUrl=sp.getString(URL_KEY,DEFAULT_URL);trackName=sp.getString(TRACK_KEY,"Pista manual");carName=sp.getString(CAR_KEY,"Carro manual");view=new MainView(this);setContentView(view);start();}
 protected void onResume(){super.onResume();start();} protected void onPause(){super.onPause();stop();}
 void start(){if(!running){running=true;handler.post(loop);}} void stop(){running=false;handler.removeCallbacks(loop);} 
 void loadTelemetry(){new Thread(()->{try{String body=http(bridgeUrl+"/api/fields");if(body==null||body.trim().length()==0)body=http(bridgeUrl+"/api/telemetry");flat=flatten(body);autoSaveLap();}catch(Exception e){try{flat.put("__status","OFFLINE");}catch(Exception ignored){}}runOnUiThread(()->view.invalidate());}).start();}
 String http(String u)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(u).openConnection();c.setConnectTimeout(900);c.setReadTimeout(900);BufferedReader br=new BufferedReader(new InputStreamReader(c.getInputStream()));StringBuilder sb=new StringBuilder();String line;while((line=br.readLine())!=null)sb.append(line);br.close();c.disconnect();return sb.toString();}
 JSONObject flatten(String body)throws Exception{JSONObject out=new JSONObject();String s=body.trim();int a=s.indexOf('{'),b=s.lastIndexOf('}');Object root=new JSONTokener(a>=0&&b>a?s.substring(a,b+1):s).nextValue();flatInto(out,"",root);return out;}
 void flatInto(JSONObject out,String prefix,Object obj)throws Exception{if(obj instanceof JSONObject){JSONObject o=(JSONObject)obj;Iterator<String> it=o.keys();while(it.hasNext()){String k=it.next();Object v=o.get(k);String p=prefix.length()==0?k:prefix+"."+k;flatInto(out,p,v);if(v instanceof JSONObject&&(k.equals("fields")||k.equals("telemetry")||k.equals("position")))flatInto(out,"",v);}}else if(obj instanceof JSONArray){JSONArray a=(JSONArray)obj;for(int i=0;i<a.length();i++)flatInto(out,prefix+"."+i,a.get(i));}else out.put(prefix,String.valueOf(obj));}
 String val(String...keys){try{for(String k:keys)if(flat.has(k)&&!flat.isNull(k)){String v=String.valueOf(flat.get(k));if(v.length()>0&&!v.equals("null")&&!v.equals("--"))return v;}}catch(Exception e){}return "--";}
 int intVal(String...keys){try{return Math.round(Float.parseFloat(val(keys).replace(",",".")));}catch(Exception e){return 0;}}
 String lapTime(){return val("lastLaptime","lastLap","last_lap","last_lap_text","ultimaVolta");}
 String bestTime(){return val("bestLaptime","bestLap","best_lap","best_lap_text","melhorVolta");}
 String lapNo(){return val("lapCount","lap","currentLap","completed_laps","voltasCorrigidas");}
 void autoSaveLap(){String lap=lapTime();if(lap.equals("--")||lap.equals(lastSavedLap))return;lastSavedLap=lap;try{JSONArray arr=new JSONArray(getSharedPreferences(PREF,0).getString(LAPS_KEY,"[]"));JSONObject o=new JSONObject();o.put("date",new SimpleDateFormat("dd/MM/yyyy HH:mm",Locale.getDefault()).format(new Date()));o.put("track",trackName);o.put("car",carName);o.put("lap",lap);o.put("best",bestTime());o.put("lapNo",lapNo());o.put("speed",val("speed_kmh","speedKmh","velocityKmh","velocidade","kmh","speed"));o.put("fuel",val("fuelPercent","fuel_percent","combustivelPorcentagem"));arr.put(o);getSharedPreferences(PREF,0).edit().putString(LAPS_KEY,arr.toString()).apply();}catch(Exception e){}}
 void setManual(String key,String title,String old){EditText input=new EditText(this);input.setText(old);new AlertDialog.Builder(this).setTitle(title).setView(input).setPositiveButton("Salvar",(d,w)->{String v=input.getText().toString().trim();if(v.length()>0){SharedPreferences.Editor ed=getSharedPreferences(PREF,0).edit();ed.putString(key,v).apply();if(key.equals(TRACK_KEY))trackName=v;if(key.equals(CAR_KEY))carName=v;view.invalidate();}}).setNegativeButton("Cancelar",null).show();}
 void setBridge(){EditText input=new EditText(this);input.setText(bridgeUrl);new AlertDialog.Builder(this).setTitle("Bridge URL").setView(input).setPositiveButton("Salvar",(d,w)->{bridgeUrl=input.getText().toString().trim();if(!bridgeUrl.startsWith("http"))bridgeUrl="http://"+bridgeUrl;getSharedPreferences(PREF,0).edit().putString(URL_KEY,bridgeUrl).apply();}).setNegativeButton("Cancelar",null).show();}
 void clearSessions(){new AlertDialog.Builder(this).setTitle("Apagar sessões?").setPositiveButton("Apagar",(d,w)->{getSharedPreferences(PREF,0).edit().putString(LAPS_KEY,"[]").apply();view.invalidate();}).setNegativeButton("Cancelar",null).show();}

 class MainView extends View{Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);RectF r=new RectF();float scale=1,scroll=0,lastY=0;int tab=0;ArrayList<Field> fields=new ArrayList<>();
  MainView(Activity a){super(a);setBackgroundColor(Color.BLACK);buildFields();}
  void buildFields(){add("Speed km/h","speed_kmh","speedKmh","velocityKmh","velocidade","kmh","speed");add("RPM","rpm","EngineRPM","engineRPM","engine_rpm","currentRpm");add("Gear","gear","currentGear","marcha","gears");add("Throttle","throttle","throttleFiltered","throttle_percent","acelerador");add("Brake","brake","brakeFiltered","brake_percent","freio");add("Fuel Capacity","fuelCapacity","fuel_capacity","tank_capacity");add("Fuel Percent","fuelPercent","fuel_percent","combustivelPorcentagem");add("Fuel Level L","fuelLevel","fuel","fuelLiters","fuel_liters");add("Lap Count","lapCount","lap","currentLap","completed_laps","voltasCorrigidas");add("Total Laps","totalLaps","raceTotalLaps");add("Last Lap","lastLaptime","lastLap","last_lap","last_lap_text","ultimaVolta");add("Best Lap","bestLaptime","bestLap","best_lap","best_lap_text","melhorVolta");add("Current Lap Time","currentLapTime","current_lap_text");add("Position X","position.x","positionX","posX","x");add("Position Y","position.y","positionY","posY","y");add("Position Z","position.z","positionZ","posZ","z");add("Water Temp","waterTemp","coolantTemp","water_temp","temperaturaAgua");add("Oil Temp","oilTemp","oil_temp");add("Oil Pressure","oilPressure","oil_pressure");add("Boost","boost","turbo","boostPressure","turbo_pressure");add("Tyre FL","tyreTempFL","tireTempFL","tyreTemp.0","tire_fl");add("Tyre FR","tyreTempFR","tireTempFR","tyreTemp.1","tire_fr");add("Tyre RL","tyreTempRL","tireTempRL","tyreTemp.2","tire_rl");add("Tyre RR","tyreTempRR","tireTempRR","tyreTemp.3","tire_rr");add("G Lateral","sway","gForceLat","g_lat","lateralG");add("G Longitudinal","surge","gForceLong","g_long","longitudinalG");add("G Vertical","heave","gForceVert","g_vertical","verticalG");add("Susp FL","suspHeightFL","suspensionFL","suspHeight.0","susp_fl");add("Susp FR","suspHeightFR","suspensionFR","suspHeight.1","susp_fr");add("Wheel RPS FL","wheelRPSFL","wheelRpsFL","wheelRPS.0","wheel_rps_fl");add("Wheel RPS FR","wheelRPSFR","wheelRpsFR","wheelRPS.1","wheel_rps_fr");add("Clutch","clutch");add("Transmission Top Speed","transmissionTopSpeed");add("Calc Max Speed","calcMaxSpeed","calculatedMaxSpeed","maxSpeed");add("Car Code","carCode","car_code","codigoCarro");add("Track Name","trackName","track","pista","circuit");add("Car Name","carName","car","modelo");add("Car Category","carCategory");}
  void add(String name,String...keys){fields.add(new Field(name,keys));}
  protected void onDraw(Canvas c){scale=getWidth()/430f;c.save();c.scale(scale,scale);draw(c,430,getHeight()/scale);c.restore();}
  void draw(Canvas c,float w,float h){p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(0,5,10));c.drawRect(0,0,w,h,p);header(c,w);if(tab==0)scanner(c,w,h);else sessions(c,w,h);nav(c,w,h);}
  void header(Canvas c,float w){txt(c,"GT7 BRIDGE MOBILE "+VERSION,14,28,16,Color.WHITE,1,Paint.Align.LEFT);txt(c,trackName+" · "+carName,14,46,9,Color.rgb(80,190,255),0,Paint.Align.LEFT);txt(c,"BRIDGE",w-18,28,10,Color.rgb(255,80,100),1,Paint.Align.RIGHT);txt(c,"PISTA",w-82,48,9,Color.WHITE,1,Paint.Align.RIGHT);txt(c,"CARRO",w-18,48,9,Color.WHITE,1,Paint.Align.RIGHT);}
  void scanner(Canvas c,float w,float h){c.save();c.translate(0,-scroll);float y=66;int shown=0,ok=0;for(int i=0;i<fields.size();i++){if(hidden(i))continue;Field f=fields.get(i);String v=value(f);if(!v.equals("--"))ok++;row(c,i,y,f.name,v);y+=44;shown++;}c.restore();footer(c,h,"Scanner · visíveis "+shown+" · funcionando "+ok+" · total "+fields.size());}
  void sessions(Canvas c,float w,float h){JSONArray arr=sessionsArray();int total=arr.length();HashSet<String> tracks=new HashSet<>(),cars=new HashSet<>();try{for(int i=0;i<arr.length();i++){JSONObject o=arr.getJSONObject(i);tracks.add(o.optString("track"));cars.add(o.optString("car"));}}catch(Exception e){}c.save();c.translate(0,-scroll);float y=68;box(c,12,y,406,90);txt(c,"SESSÕES",24,y+26,14,Color.WHITE,1,Paint.Align.LEFT);txt(c,""+total,88,y+62,22,Color.WHITE,1,Paint.Align.CENTER);txt(c,"VOLTAS",88,y+78,8,Color.rgb(180,180,180),0,Paint.Align.CENTER);txt(c,""+tracks.size(),215,y+62,22,Color.WHITE,1,Paint.Align.CENTER);txt(c,"PISTAS",215,y+78,8,Color.rgb(180,180,180),0,Paint.Align.CENTER);txt(c,""+cars.size(),340,y+62,22,Color.WHITE,1,Paint.Align.CENTER);txt(c,"CARROS",340,y+78,8,Color.rgb(180,180,180),0,Paint.Align.CENTER);y+=106;try{for(int i=arr.length()-1;i>=0;i--){JSONObject o=arr.getJSONObject(i);box(c,12,y,406,82);txt(c,o.optString("track"),24,y+22,12,Color.WHITE,1,Paint.Align.LEFT);txt(c,o.optString("lap"),400,y+22,13,Color.WHITE,1,Paint.Align.RIGHT);txt(c,o.optString("car"),24,y+44,11,Color.rgb(220,220,220),1,Paint.Align.LEFT);txt(c,o.optString("date")+" · volta "+o.optString("lapNo"),24,y+64,9,Color.rgb(150,150,150),0,Paint.Align.LEFT);y+=90;}}catch(Exception e){}c.restore();footer(c,h,"Sessões gravadas automaticamente pela última volta");}
  JSONArray sessionsArray(){try{return new JSONArray(getSharedPreferences(PREF,0).getString(LAPS_KEY,"[]"));}catch(Exception e){return new JSONArray();}}
  void row(Canvas c,int index,float y,String name,String val){boolean ok=!val.equals("--");r.set(10,y,420,y+38);p.setStyle(Paint.Style.FILL);p.setColor(ok?Color.rgb(3,24,20):Color.rgb(12,16,22));c.drawRoundRect(r,8,8,p);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1);p.setColor(ok?Color.rgb(0,130,90):Color.rgb(45,70,90));c.drawRoundRect(r,8,8,p);txt(c,name,20,y+16,10,Color.rgb(180,215,235),0,Paint.Align.LEFT);txt(c,val,20,y+32,12,ok?Color.WHITE:Color.rgb(100,120,130),1,Paint.Align.LEFT);txt(c,"X",398,y+25,15,Color.rgb(255,75,95),1,Paint.Align.CENTER);}
  String value(Field f){try{for(String k:f.keys){if(flat.has(k)&&!flat.isNull(k)){String v=String.valueOf(flat.get(k));if(v.length()>0&&!v.equals("null"))return v;}}}catch(Exception e){}return "--";}
  boolean hidden(int i){return getSharedPreferences(PREF,0).getBoolean("hide_"+i,false);}
  public boolean onTouchEvent(MotionEvent e){float x=e.getX()/scale,y=e.getY()/scale;if(e.getAction()==MotionEvent.ACTION_DOWN){lastY=y;return true;}if(e.getAction()==MotionEvent.ACTION_MOVE){scroll=Math.max(0,scroll-(y-lastY));lastY=y;invalidate();return true;}if(e.getAction()==MotionEvent.ACTION_UP){if(y<56&&x>350){setBridge();return true;}if(y<56&&x>270&&x<350){setManual(TRACK_KEY,"Nome da pista",trackName);return true;}if(y<56&&x>205&&x<270){setManual(CAR_KEY,"Nome do carro",carName);return true;}if(y>getHeight()/scale-58){tab=x<215?0:1;scroll=0;invalidate();return true;}if(tab==0){int row=(int)((y+scroll-66)/44);if(row>=0&&x>365){int real=-1,count=-1;for(int i=0;i<fields.size();i++){if(hidden(i))continue;count++;if(count==row){real=i;break;}}if(real>=0){getSharedPreferences(PREF,0).edit().putBoolean("hide_"+real,true).apply();invalidate();return true;}}}if(tab==1&&x>330&&y<120){clearSessions();return true;}}return true;}
  void footer(Canvas c,float h,String s){p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(0,5,10));c.drawRect(0,h-82,430,h,p);txt(c,s,14,h-64,9,Color.WHITE,0,Paint.Align.LEFT);}
  void nav(Canvas c,float w,float h){float y=h-50;box(c,8,y,414,42);txt(c,"SCANNER",108,y+27,11,tab==0?Color.rgb(0,230,130):Color.WHITE,1,Paint.Align.CENTER);txt(c,"SESSÕES",322,y+27,11,tab==1?Color.rgb(0,230,130):Color.WHITE,1,Paint.Align.CENTER);}
  void box(Canvas c,float x,float y,float w,float h){r.set(x,y,x+w,y+h);p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(14,16,18));c.drawRoundRect(r,8,8,p);p.setStyle(Paint.Style.STROKE);p.setColor(Color.rgb(45,45,45));p.setStrokeWidth(1);c.drawRoundRect(r,8,8,p);} 
  void txt(Canvas c,String s,float x,float y,float sz,int col,int bold,Paint.Align a){p.setStyle(Paint.Style.FILL);p.setColor(col);p.setTextSize(sz);p.setTextAlign(a);p.setTypeface(bold==1?Typeface.create(Typeface.SANS_SERIF,Typeface.BOLD):Typeface.create(Typeface.SANS_SERIF,Typeface.NORMAL));c.drawText(s==null?"--":s,x,y,p);}
 }
 static class Field{String name;String[] keys;Field(String n,String[] k){name=n;keys=k;}}
}
